solution:
#include <stdio.h>

int main(void) {
    int pressure;
    scanf("%d", &pressure);
    if (pressure < 95) {
        printf("LOW\n");
    } else if (pressure > 105) {
        printf("HIGH\n");
    } else {
        printf("OPEN\n");
    }
    return 0;
}
